const crypto = require('crypto');
// n8n exposes the raw body on the webhook node when rawBody:true.
const raw = $input.first().json.body !== undefined
  ? (typeof $input.first().json.body === 'string' ? $input.first().json.body : JSON.stringify($input.first().json.body))
  : ($input.first().binary ? Buffer.from($input.first().binary.data.data, 'base64').toString('utf8') : '');
const headers = $input.first().json.headers || {};
const sig = headers['x-documenso-signature'] || headers['X-Documenso-Signature'] || '';
const secret = $env.DOCUMENSO_WEBHOOK_SECRET || '';

let valid = false;
try {
  const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
  valid = sig.length > 0 && crypto.timingSafeEqual(
    Buffer.from(expected),
    Buffer.from((sig + '0'.repeat(expected.length)).slice(0, expected.length))
  );
} catch (e) { valid = false; }

let payload = {};
try { payload = JSON.parse(raw); } catch (e) {}
const title = payload?.payload?.title || payload?.data?.title || payload?.title || '';
// proposal_ref format: UW-<lead_id>-<date>-<seq>
const leadId = parseInt(String(title).replace(/^UW-/, '').split('-')[0], 10) || null;

return [{ json: {
  valid: String(valid),
  proposal_ref: title,
  lead_id: leadId,
  envelope_id: payload?.payload?.id || payload?.data?.id || null,
  event: payload?.event || null
} }];
